function dispatch(first, second) {
  first.slice().forEach(fn => fn());
  second.slice().forEach(fn => fn());
}
const log = []; const second = [];
dispatch([() => second.push(() => log.push("late"))], second);

function dispatch(first, second) {
  const a = first.slice(); const b = second.slice();
  a.forEach(fn => fn()); b.forEach(fn => fn());
}
const log = []; const second = [];
dispatch([() => second.push(() => log.push("late"))], second);

function invoke(callback, value) {
  try { callback(value); return "returned"; }
  catch { return "caught"; }
}
const result = invoke(value => value.toUpperCase());
